<div class="auth-card"><div class="auth-heading"><span class="eyebrow">Account recovery</span><h2>Choose a new password</h2><p>Use a strong password you do not reuse on another service.</p></div><form method="post" action="<?= url('reset-password/'.$token) ?>" class="auth-form"><?= csrf_field() ?><label><span>New password</span><input type="password" name="password" required minlength="10" autocomplete="new-password" autofocus><?= error('password')?'<small class="field-error">'.e(error('password')).'</small>':'' ?></label><label><span>Confirm password</span><input type="password" name="password_confirmation" required autocomplete="new-password"></label><button class="button button-primary button-block" type="submit">Update password →</button></form></div>
